import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Standard Archenemy","description":"","frontmatter":{},"headers":[],"relativePath":"formats/archenemy/variants/standard.md","filePath":"formats/archenemy/variants/standard.md","lastUpdated":null}'),o={name:"formats/archenemy/variants/standard.md"};function s(i,e,h,l,c,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="standard-archenemy" tabindex="-1">Standard Archenemy <a class="header-anchor" href="#standard-archenemy" aria-label="Permalink to &quot;Standard Archenemy&quot;">​</a></h1><p><a href="./../">Archenemy versions</a> · <strong>Rules: traditional team game</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>Use one archenemy and a team of heroes. The published format recommends three or more heroes; the comprehensive rules allow a team of any size.</p><p>Each player supplies an ordinary constructed deck of at least 60 cards, using the group&#39;s agreed card pool and the normal four-copy limit except basic lands and card-specific exceptions. The archenemy also needs at least 20 scheme cards, with at most two cards of any one English name. Supply tokens and counters required by the cards.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Choose the archenemy and the hero team.</li><li>Shuffle every ordinary deck and the scheme deck separately.</li><li>Set the archenemy to <strong>40 life</strong> and each hero to <strong>20 life</strong>. Hero life totals are separate.</li><li>Draw seven cards each and take normal multiplayer mulligans.</li><li>Put the face-down scheme deck in the command zone. No scheme starts in motion unless another effect says so.</li><li>The archenemy takes the first turn.</li></ol><h2 id="turns-and-combat" tabindex="-1">Turns and combat <a class="header-anchor" href="#turns-and-combat" aria-label="Permalink to &quot;Turns and combat&quot;">​</a></h2><p>The archenemy takes the first turn and draws during their first draw step. Then the hero team takes a shared turn. Alternate archenemy turns and team turns.</p><p>During a team turn, heroes move through the phases and steps together. Each untaps their own permanents, takes their own draw, and may use their own land play. They make their own decisions, pay their own costs, and keep their own hands, libraries, mana, and permanents. Being teammates does not let them spend one another&#39;s mana or cards.</p><p>The heroes declare their attacks together against the archenemy or legal objects that can be attacked. When the archenemy attacks, declare which hero or attackable object each creature attacks. Heroes declare blockers together and can use their creatures to defend a teammate or that teammate&#39;s planeswalker. They cannot attack one another.</p><p>Use the shared-team-turn rules for priority, simultaneous decisions, and combat. Individual card restrictions still apply; being on a team does not allow an otherwise illegal target or block.</p><h2 id="setting-schemes-in-motion" tabindex="-1">Setting schemes in motion <a class="header-anchor" href="#setting-schemes-in-motion" aria-label="Permalink to &quot;Setting schemes in motion&quot;">​</a></h2><p>Keep the scheme deck shuffled, face down in the command zone, separate from the ordinary library. Its owner cannot inspect or rearrange it without an effect allowing that.</p><p>As the archenemy&#39;s precombat main phase begins on each of their turns, turn the top scheme face up in the command zone. This mandatory turn-based action sets the scheme in motion and does not use the stack. Abilities that trigger from it do use the stack, so players can respond to those abilities.</p><p>Choose targets when putting a triggered ability on the stack. Make choices or payments that the effect asks for during resolution at that time, rather than while revealing the scheme.</p><p>Schemes stay in the command zone. They are not battlefield permanents, cannot be cast, and cannot be destroyed with an effect that destroys a permanent. A face-up scheme&#39;s abilities function from the command zone.</p><h3 id="non-ongoing-schemes" tabindex="-1">Non-ongoing schemes <a class="header-anchor" href="#non-ongoing-schemes" aria-label="Permalink to &quot;Non-ongoing schemes&quot;">​</a></h3><p>A face-up, non-ongoing scheme goes face down on the bottom of its owner&#39;s scheme deck as a state-based action once no scheme triggered abilities are on the stack or waiting to be put there. Countering its ability does not leave the scheme permanently face up.</p><h3 id="ongoing-schemes" tabindex="-1">Ongoing schemes <a class="header-anchor" href="#ongoing-schemes" aria-label="Permalink to &quot;Ongoing schemes&quot;">​</a></h3><p>An ongoing scheme stays face up until an ability tells its controller to abandon it. Abandoning it turns it face down and puts it on the bottom of its owner&#39;s scheme deck. Its printed condition determines when that happens; revealing another scheme does not automatically abandon it.</p><p>Follow individual scheme instructions for additional schemes, costs, choices, and exceptions. A scheme asking an opponent to choose “self” or “others” still permits “others” when that opponent has no teammates, even if that option affects nobody.</p><h2 id="winning-losing-and-leaving" tabindex="-1">Winning, losing, and leaving <a class="header-anchor" href="#winning-losing-and-leaving" aria-label="Permalink to &quot;Winning, losing, and leaving&quot;">​</a></h2><p>The archenemy wins when every hero has lost. The hero team wins when the archenemy loses, including heroes who were eliminated earlier. If the archenemy and the last hero lose simultaneously, the game is a draw.</p><p>Each player&#39;s ordinary loss conditions still apply: zero or less life, drawing from an empty library, ten poison counters, or a relevant card effect. A hero losing does not eliminate the other heroes.</p><p>When a player leaves, remove their owned objects, end effects that gave them control of other players&#39; objects, and apply the remaining multiplayer leaving-the-game rules. Do not simply leave an eliminated hero&#39;s creatures under the team&#39;s control.</p><h2 id="other-versions-and-references" tabindex="-1">Other versions and references <a class="header-anchor" href="#other-versions-and-references" aria-label="Permalink to &quot;Other versions and references&quot;">​</a></h2><p>For Commander decks with shared hero life, use <a href="./commander.html">Archenemy Commander</a>. For everyone having schemes, use <a href="./rumble.html">Supervillain Rumble</a>.</p><p>Sources: <a href="https://magic.wizards.com/en/formats/archenemy" target="_blank" rel="noreferrer">Wizards&#39; format rules</a>, <a href="https://magic.wizards.com/en/news/feature/archenemy-rules-revealed-2010-05-17" target="_blank" rel="noreferrer">original rules explanation</a>, and <a href="https://magic.wizards.com/en/rules" target="_blank" rel="noreferrer">Comprehensive Rules</a> 314, 805, 808, and 904. The current mulligan procedure comes from normal Magic rules rather than the older article&#39;s historical wording.</p>',29)])])}const u=a(o,[["render",s]]);export{p as __pageData,u as default};
